/* [[vcms:component:header:start]] */
* { box-sizing: border-box; } body {margin: 0;}*{box-sizing:border-box;}body{margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;}*{box-sizing:border-box;}body{margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;}*{box-sizing:border-box;}body{margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;}

/* Ícone hambúrguer -> X (sem JS): 3 barras que giram/desaparecem
   conforme o estado :focus-within do .dropdown (o mesmo estado que o
   DaisyUI já usa para abrir/fechar o menu mobile). Todas as 3 barras usam
   translate(-50%,-50%) para ficarem centralizadas de forma idêntica —
   qualquer barra sem esse recuo vertical fica com espaçamento desigual
   em relação às outras. display/margin/padding explícitos removem
   qualquer resquício de estilo de <span> (inline) que possa interferir. */
.vcms-burger { position: relative; }
.vcms-burger-bar {
  display: block;
  position: absolute;
  left: 50%;
  width: 18px;
  height: 2px;
  margin: 0;
  padding: 0;
  background: currentColor;
  border-radius: 1px;
  transition: transform .25s ease, opacity .2s ease;
}
.vcms-burger-bar-1 { top: calc(50% - 6px); transform: translate(-50%, -50%); }
.vcms-burger-bar-2 { top: 50%;             transform: translate(-50%, -50%); }
.vcms-burger-bar-3 { top: calc(50% + 6px); transform: translate(-50%, -50%); }
.dropdown:focus-within .vcms-burger-bar-1 { top: 50%; transform: translate(-50%, -50%) rotate(45deg); }
.dropdown:focus-within .vcms-burger-bar-2 { opacity: 0; }
.dropdown:focus-within .vcms-burger-bar-3 { top: 50%; transform: translate(-50%, -50%) rotate(-45deg); }

/* Menu mobile: abre "de cima para baixo" (desliza + revela), no lugar do
   scale uniforme padrão do DaisyUI. Escopado só para telas < lg (1024px)
   para não interferir no menu horizontal do desktop.

   O DaisyUI esconde o menu fechado com display:none, o que IMPEDE uma
   transição comum de rodar (não dá pra animar a partir de um elemento que
   não existe no layout). A abordagem com @starting-style resolveria isso,
   mas exige também `transition-behavior: allow-discrete` pra funcionar —
   sem isso a transição nunca chega a rodar. Aqui trocamos a estratégia por
   `visibility`, que anima normalmente em qualquer navegador: o menu fica
   sempre "presente" (visibility:hidden, sem display:none), anima
   opacity/transform normalmente, e só troca pra visibility:visible/hidden
   no início/fim da transição. */
@media (max-width: 1023.98px) {
  .dropdown .vcms-mobile-menu {
    display: flex;
    scale: 1;
    visibility: hidden;
    transform-origin: top center;
    transform: scaleY(0);
    opacity: 0;
    transition: transform .25s ease, opacity .2s ease, visibility 0s linear .25s;
  }
  .dropdown:focus-within .vcms-mobile-menu {
    visibility: visible;
    transform: scaleY(1);
    opacity: 1;
    transition: transform .25s ease, opacity .2s ease, visibility 0s linear;
  }
}
/* [[vcms:component:header:end]] */

